/**
 * @file ProcessMemoryPool.cpp
 * @brief Implementation of the process-wide fixed-size block pool.
 *
 * Chevron Library — Internal Infrastructure
 */

#include "ProcessMemoryPool.hpp"

#include <stdexcept>
#include <new>          // std::bad_alloc
#include <cstring>      // std::memset (debug poisoning, if desired)

// Platform-specific headers for OS memory acquisition
#if defined(__linux__) || defined(__APPLE__)
    #include <cstdlib>  // std::aligned_alloc / posix_memalign
#elif defined(_WIN32)
    #include <malloc.h> // _aligned_malloc / _aligned_free
#endif

namespace chevron::memory {

// ============================================================================
// Construction / Destruction
// ============================================================================

ProcessMemoryPool::ProcessMemoryPool(const PoolConfig& config)
    : free_list_head_{ TaggedPointer{ nullptr, 0 } }
    , block_size_{ 0 }
    , block_alignment_{ 0 }
    , chunk_size_{ 0 }
    , blocks_per_chunk_{ 0 }
    , budget_ceiling_{ 0 }
    , chunk_descriptors_{ nullptr }
    , chunk_count_{ 0 }
    , max_chunk_count_{ 0 }
    , initial_thread_batch_{ 0 }
    , max_thread_batch_{ 0 }
{
    // -- Validate raw inputs --------------------------------------------------

    if (config.block_size == 0)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: block_size must be greater than zero."
        );
    }

    if (config.block_alignment == 0)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: block_alignment must be greater than zero."
        );
    }

    // Alignment must be a power of two — this is a requirement of aligned
    // allocation APIs (aligned_alloc, posix_memalign, _aligned_malloc) and
    // of the arithmetic that relies on alignment being a clean binary mask.
    if ((config.block_alignment & (config.block_alignment - 1)) != 0)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: block_alignment must be a power of two."
        );
    }

    if (config.chunk_size == 0)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: chunk_size must be greater than zero."
        );
    }

    if (config.budget_ceiling == 0)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: budget_ceiling must be greater than zero."
        );
    }

    // -- Compute effective block size -----------------------------------------

    // The block must be large enough to hold an embedded FreeRegionNode.
    std::size_t adjusted_block_size = config.block_size;

    if (adjusted_block_size < sizeof(FreeRegionNode))
    {
        adjusted_block_size = sizeof(FreeRegionNode);
    }

    // Round up to the nearest multiple of block_alignment so that
    // contiguous block placement keeps every block aligned.
    //
    // The formula (value + alignment - 1) & ~(alignment - 1) works
    // because alignment is a power of two, making ~(alignment - 1)
    // a bitmask that clears the lower bits.
    std::size_t alignment = config.block_alignment;
    adjusted_block_size = (adjusted_block_size + alignment - 1) & ~(alignment - 1);

    block_size_ = adjusted_block_size;
    block_alignment_ = alignment;

    // -- Compute effective chunk size -----------------------------------------

    // Round chunk_size up to the nearest multiple of block_size so that
    // no space is wasted at the tail of a chunk.
    std::size_t adjusted_chunk_size = config.chunk_size;

    if (adjusted_chunk_size < block_size_)
    {
        // A chunk must hold at least one block.
        adjusted_chunk_size = block_size_;
    }

    // Round up: same power-of-two rounding won't work here because
    // block_size_ is not necessarily a power of two. Use arithmetic
    // ceiling division instead.
    std::size_t remainder = adjusted_chunk_size % block_size_;
    if (remainder != 0)
    {
        adjusted_chunk_size += block_size_ - remainder;
    }

    chunk_size_ = adjusted_chunk_size;
    blocks_per_chunk_ = chunk_size_ / block_size_;

    // -- Validate budget ceiling against chunk size ---------------------------

    if (config.budget_ceiling < chunk_size_)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: budget_ceiling must be >= the effective chunk_size. "
            "The pool cannot acquire even a single chunk within the given budget."
        );
    }

    budget_ceiling_ = config.budget_ceiling;
    max_chunk_count_ = budget_ceiling_ / chunk_size_;

    // -- Allocate chunk descriptor array --------------------------------------

    // This is the one heap allocation the pool itself makes. It is a fixed
    // array sized to hold the maximum number of chunks the pool can ever
    // acquire. We use regular new[] here — this is a small metadata array,
    // not the performance-critical block memory.
    chunk_descriptors_ = new ChunkDescriptor[max_chunk_count_];

    // Zero-initialize descriptors so that any accidental read of an
    // unoccupied slot returns a null base pointer.
    for (std::size_t i = 0; i < max_chunk_count_; ++i)
    {
        chunk_descriptors_[i].base = nullptr;
        chunk_descriptors_[i].size = 0;
    }

    // -- Store thread-local cache parameters ----------------------------------

    initial_thread_batch_ = config.initial_thread_batch;
    max_thread_batch_ = config.max_thread_batch;

    // Sanity: if initial batch is zero, default to 1 so that a thread's
    // first trip to the shared pool acquires at least one block.
    if (initial_thread_batch_ == 0)
    {
        initial_thread_batch_ = 1;
    }

    // Sanity: max batch must be >= initial batch.
    if (max_thread_batch_ < initial_thread_batch_)
    {
        max_thread_batch_ = initial_thread_batch_;
    }
}


ProcessMemoryPool::~ProcessMemoryPool()
{
    // Release every acquired chunk back to the OS.
    //
    // At this point, all threads that used this pool must have already
    // joined. Thread-local caches may still hold block pointers, but
    // those blocks reside within the chunks we are about to release as
    // whole units — individual block cleanup is unnecessary.
    //
    // We iterate only through occupied slots (0 to chunk_count_ - 1).
    // Each chunk was acquired via acquire_from_os() and must be returned
    // via release_to_os() with the same base and size.

    for (std::size_t i = 0; i < chunk_count_; ++i)
    {
        release_to_os(chunk_descriptors_[i].base, chunk_descriptors_[i].size);
    }

    // Release the descriptor array itself.
    delete[] chunk_descriptors_;
    chunk_descriptors_ = nullptr;
    chunk_count_ = 0;
}

} // namespace chevron::memory

