    #include <malloc.h> // _aligned_malloc / _aligned_free
#endif

namespace chevron::memory {

// ============================================================================
// Construction / Destruction
// ============================================================================

ProcessMemoryPool::ProcessMemoryPool(const PoolConfig& config)
    : free_list_head_{ TaggedPointer{ nullptr, 0 } }
    , chunk_descriptors_{ nullptr }
    , chunk_count_{ 0 }
{
    config.isValidOrThrow();

    compute_effective_block_geometry(config);
    compute_effective_chunk_geometry(config);
    validate_budget_constraints(config);
    init_chunk_descriptor_array();
    init_thread_cache_configuration(config);
}


ProcessMemoryPool::~ProcessMemoryPool()
{
    // Release every acquired chunk back to the OS.
    //
    // At this point, all threads that used this pool must have already
    // joined. Thread-local caches may still hold block pointers, but
    // those blocks reside within the chunks we are about to release as
    // whole units — individual block cleanup is unnecessary.
    //
    // Each chunk was acquired via acquire_from_os() and must be returned
    // via release_to_os() with the same base and size.

    for (std::size_t i = 0; i < chunk_count_; ++i)
    {
        release_to_os(chunk_descriptors_[i].base, chunk_descriptors_[i].size);
    }

    delete[] chunk_descriptors_;
    chunk_descriptors_ = nullptr;
    chunk_count_ = 0;
}


// ============================================================================
// Construction Helpers (private)
// ============================================================================

void ProcessMemoryPool::compute_effective_block_geometry(const PoolConfig& config)
{
    // The block must be large enough to hold an embedded FreeRegionNode.
    std::size_t adjusted = config.block_size;

    if (adjusted < sizeof(FreeRegionNode))
    {
        adjusted = sizeof(FreeRegionNode);
    }

    // Round up to the nearest multiple of block_alignment so that
    // contiguous block placement keeps every block aligned.
    //
    // The formula (value + alignment - 1) & ~(alignment - 1) works
    // because alignment is guaranteed to be a power of two (validated
    // by PoolConfig), making ~(alignment - 1) a bitmask that clears
    // the lower bits.
    std::size_t alignment = config.block_alignment;
    adjusted = (adjusted + alignment - 1) & ~(alignment - 1);

    block_size_ = adjusted;
    block_alignment_ = alignment;
}


void ProcessMemoryPool::compute_effective_chunk_geometry(const PoolConfig& config)
{
    // Round chunk_size up to the nearest multiple of block_size so that
    // no space is wasted at the tail of a chunk.
    std::size_t adjusted = config.chunk_size;

    if (adjusted < block_size_)
    {
        // A chunk must hold at least one block.
        adjusted = block_size_;
    }

    // Round up: the power-of-two bitmask trick does not apply here
    // because block_size_ is not necessarily a power of two. Use
    // arithmetic ceiling instead.
    std::size_t remainder = adjusted % block_size_;
    if (remainder != 0)
    {
        adjusted += block_size_ - remainder;
    }

    chunk_size_ = adjusted;
    blocks_per_chunk_ = chunk_size_ / block_size_;
}


void ProcessMemoryPool::validate_budget_constraints(const PoolConfig& config)
{
    // This check depends on effective chunk_size_ which has already been
    // computed. The budget must accommodate at least one effective chunk.
    if (config.budget_ceiling < chunk_size_)
    {
        throw std::invalid_argument(
            "ProcessMemoryPool: budget_ceiling must be >= the effective chunk_size. "
            "The pool cannot acquire even a single chunk within the given budget."
        );
    }

    budget_ceiling_ = config.budget_ceiling;
    max_chunk_count_ = budget_ceiling_ / chunk_size_;
}


void ProcessMemoryPool::init_chunk_descriptor_array()
{
    // This is the one heap allocation the pool itself makes. It is a
    // fixed array sized to hold the maximum number of chunks the pool
    // can ever acquire. Regular new[] is appropriate here — this is a
    // small metadata array, not performance-critical block memory.
    chunk_descriptors_ = new ChunkDescriptor[max_chunk_count_];

    // Zero-initialize descriptors so that any accidental read of an
    // unoccupied slot returns a null base pointer.
    for (std::size_t i = 0; i < max_chunk_count_; ++i)
    {
        chunk_descriptors_[i].base = nullptr;
        chunk_descriptors_[i].size = 0;
    }
}


void ProcessMemoryPool::init_thread_cache_configuration(const PoolConfig& config)
{
    initial_thread_batch_ = config.initial_thread_batch;
    max_thread_batch_ = config.max_thread_batch;

    // Sanity: if initial batch is zero, default to 1 so that a thread's
    // first trip to the shared pool acquires at least one block.
    if (initial_thread_batch_ == 0)
    {
        initial_thread_batch_ = 1;
    }

    // Sanity: max batch must be >= initial batch.
    if (max_thread_batch_ < initial_thread_batch_)
    {
        max_thread_batch_ = initial_thread_batch_;
    }
}

} // namespace chevron::memory

