#include "ProcessMemoryPool.hpp"

#include <stdexcept>

namespace chevron::memory {

// ============================================================================
// PoolConfig Validation
// ============================================================================

bool PoolConfig::validate(std::string& reason) const
{
    if (block_size == 0)
    {
        reason = "PoolConfig: block_size must be greater than zero.";
        return false;
    }

    if (block_alignment == 0)
    {
        reason = "PoolConfig: block_alignment must be greater than zero.";
        return false;
    }

    // Alignment must be a power of two — this is a requirement of aligned
    // allocation APIs (aligned_alloc, posix_memalign, _aligned_malloc) and
    // of the arithmetic that relies on alignment being a clean binary mask.
    if ((block_alignment & (block_alignment - 1)) != 0)
    {
        reason = "PoolConfig: block_alignment must be a power of two.";
        return false;
    }

    if (chunk_size == 0)
    {
        reason = "PoolConfig: chunk_size must be greater than zero.";
        return false;
    }

    if (budget_ceiling == 0)
    {
        reason = "PoolConfig: budget_ceiling must be greater than zero.";
        return false;
    }

    return true;
}


bool PoolConfig::isValid() const noexcept
{
    std::string unused;
    return validate(unused);
}


void PoolConfig::isValidOrThrow() const
{
    std::string reason;

    if (!validate(reason))
    {
        throw std::invalid_argument(reason);
    }
}

} // namespace chevron::memory

