/**
 * @file ProcessMemoryAllocator.cpp
 * @brief Implementation of OS memory acquisition and chunk tracking.
 *
 * Chevron Library — Internal Infrastructure
 */

#include "ProcessMemoryAllocator.hpp"
#include "ProcessMemoryPool.hpp"  // ChunkDescriptor definition

#include <stdexcept>
#include <new>  // std::bad_alloc

// Platform-specific headers for aligned allocation
#if defined(__linux__) || defined(__APPLE__)
    #include <cstdlib>  // std::aligned_alloc
#elif defined(_WIN32)
    #include <malloc.h> // _aligned_malloc / _aligned_free
#endif

namespace chevron::memory {

// ============================================================================
// Construction / Destruction
// ============================================================================

ProcessMemoryAllocator::ProcessMemoryAllocator(std::size_t max_chunk_count)
    : chunk_descriptors_{ nullptr }
    , chunk_count_{ 0 }
    , max_chunk_count_{ max_chunk_count }
{
    if (max_chunk_count_ == 0)
    {
        throw std::invalid_argument(
            "ProcessMemoryAllocator: max_chunk_count must be greater than zero."
        );
    }

    chunk_descriptors_ = new ChunkDescriptor[max_chunk_count_];

    for (std::size_t i = 0; i < max_chunk_count_; ++i)
    {
        chunk_descriptors_[i].base = nullptr;
        chunk_descriptors_[i].size = 0;
    }
}


ProcessMemoryAllocator::~ProcessMemoryAllocator()
{
    // All threads must have joined before destruction. Load relaxed
    // because no concurrent access is possible at this point.
    std::size_t count = chunk_count_.load(std::memory_order_relaxed);

    for (std::size_t i = 0; i < count; ++i)
    {
        deallocate_aligned(chunk_descriptors_[i].base, chunk_descriptors_[i].size);
    }

    delete[] chunk_descriptors_;
    chunk_descriptors_ = nullptr;
}


// ============================================================================
// Chunk Acquisition
// ============================================================================

void* ProcessMemoryAllocator::acquire_chunk(
    std::size_t size,
    std::size_t alignment
)
{
    // Atomically claim a slot in the descriptor array. fetch_add returns
    // the previous value, which becomes our exclusive slot index.
    std::size_t slot = chunk_count_.fetch_add(1, std::memory_order_acq_rel);

    if (slot >= max_chunk_count_)
    {
        // No room in the descriptor array — roll back and signal failure.
        chunk_count_.fetch_sub(1, std::memory_order_relaxed);
        throw std::bad_alloc();
    }

    // Acquire aligned memory from the OS. If this fails, roll back the
    // counter so the slot is not permanently consumed.
    void* base = nullptr;

    try
    {
        base = allocate_aligned(size, alignment);
    }
    catch (...)
    {
        chunk_count_.fetch_sub(1, std::memory_order_relaxed);
        throw;
    }

    // Record the chunk in our exclusively claimed slot. No other thread
    // can write to this slot because fetch_add guaranteed uniqueness.
    chunk_descriptors_[slot].base = base;
    chunk_descriptors_[slot].size = size;

    return base;
}


// ============================================================================
// Diagnostics
// ============================================================================

std::size_t ProcessMemoryAllocator::acquired_count() const noexcept
{
    return chunk_count_.load(std::memory_order_relaxed);
}


std::size_t ProcessMemoryAllocator::max_count() const noexcept
{
    return max_chunk_count_;
}


// ============================================================================
// Platform Abstraction (private, static)
// ============================================================================

void* ProcessMemoryAllocator::allocate_aligned(
    std::size_t size,
    std::size_t alignment
)
{
    void* ptr = nullptr;

#if defined(_WIN32)

    ptr = _aligned_malloc(size, alignment);

    if (!ptr)
    {
        throw std::bad_alloc();
    }

#elif defined(__linux__) || defined(__APPLE__)

    // std::aligned_alloc requires size to be a multiple of alignment.
    // This should already be the case given the pool's geometry rounding,
    // but as a safety measure we round size up here to guarantee it.
    std::size_t adjusted_size = size;
    std::size_t remainder = adjusted_size % alignment;
    if (remainder != 0)
    {
        adjusted_size += alignment - remainder;
    }

    ptr = std::aligned_alloc(alignment, adjusted_size);

    if (!ptr)
    {
        throw std::bad_alloc();
    }

#else
    #error "ProcessMemoryAllocator: unsupported platform."
#endif

    return ptr;
}


void ProcessMemoryAllocator::deallocate_aligned(
    [[maybe_unused]] void* base,
    [[maybe_unused]] std::size_t size
) noexcept
{
#if defined(_WIN32)

    _aligned_free(base);

#elif defined(__linux__) || defined(__APPLE__)

    std::free(base);

#endif
}

} // namespace chevron::memory

