    std::size_t previous = chunk_count_.fetch_add(1, std::memory_order_acq_rel);

    if (previous >= max_chunk_count_)
    {
        chunk_count_.fetch_sub(1, std::memory_order_relaxed);
        throw std::bad_alloc();
    }

    // ---- Phase 2: OS acquisition ---------------------------------------------
    //
    // Request aligned memory from the OS. If this fails, roll back the
    // budget counter and rethrow. The tracking list is untouched — no
    // node was created, no CAS was attempted. The failure path is clean.

    void* base = nullptr;

    try
    {
        base = allocate_aligned(size, alignment);
    }
    catch (...)
    {
        chunk_count_.fetch_sub(1, std::memory_order_relaxed);
        throw;
    }

    // ---- Phase 3: Tracking node construction ---------------------------------
    //
    // Allocate a tracking node via regular new and populate it with the
    // chunk's descriptor data. The node is fully initialized before it
    // is pushed onto the list — no thread can observe a partially
    // constructed node.

    ChunkNode* node = new ChunkNode{
        ChunkDescriptor{ base, size, alignment },
        nullptr
    };

    // ---- Phase 4: CAS push onto tracking list --------------------------------
    //
    // Prepend the node to the list head via compare-and-swap. Read the
    // current head into the node's next pointer. Attempt to swap the
    // head from the current value to the new node. If another thread
    // pushed between the read and the swap, compare_exchange_weak fails
    // and updates node->next to the new head automatically, and we retry.
    //
    // No tagged pointer is needed because nodes are only ever pushed —
    // never popped during runtime. The ABA precondition (a node leaving
    // and re-entering the list) cannot occur.
    //
    // memory_order_release on success ensures that the node's descriptor
    // writes are visible to any thread that later reads the list (the
    // destructor). memory_order_relaxed on failure is safe because the
    // failed CAS has no side effects — we just retry with the updated
    // head value.

    node->next = head_.load(std::memory_order_acquire);

    while (!head_.compare_exchange_weak(
        node->next,
        node,
        std::memory_order_release,
        std::memory_order_relaxed
    ))
    {
        // node->next is automatically updated by compare_exchange_weak
        // to the current value of head_ on failure. The loop retries
        // with the corrected next pointer.
    }

    return base;
}


// ============================================================================
// Diagnostics
// ============================================================================

std::size_t ProcessMemoryAllocator::acquired_count() const noexcept
{
    return chunk_count_.load(std::memory_order_relaxed);
}


std::size_t ProcessMemoryAllocator::max_count() const noexcept
{
    return max_chunk_count_;
}


// ============================================================================
// Platform Abstraction (private, static)
// ============================================================================

void* ProcessMemoryAllocator::allocate_aligned(
    std::size_t size,
    std::size_t alignment
)
{
    void* ptr = nullptr;

#if defined(_WIN32)

    ptr = _aligned_malloc(size, alignment);

    if (!ptr)
    {
        throw std::bad_alloc();
    }

#elif defined(__linux__) || defined(__APPLE__)

    // std::aligned_alloc requires size to be a multiple of alignment.
    // This should already be the case given the pool's geometry rounding,
    // but as a safety measure we round size up here to guarantee it.
    std::size_t adjusted_size = size;
    std::size_t remainder = adjusted_size % alignment;
    if (remainder != 0)
    {
        adjusted_size += alignment - remainder;
    }

    ptr = std::aligned_alloc(alignment, adjusted_size);

    if (!ptr)
    {
        throw std::bad_alloc();
    }

#else
    #error "ProcessMemoryAllocator: unsupported platform."
#endif

    return ptr;
}


void ProcessMemoryAllocator::deallocate_aligned(
    [[maybe_unused]] void* base,
    [[maybe_unused]] std::size_t size
) noexcept
{
#if defined(_WIN32)

    _aligned_free(base);

#elif defined(__linux__) || defined(__APPLE__)

    std::free(base);

#endif
}

