void ProcessMemoryPool::compute_effective_block_geometry()
{
    // The block must be large enough to hold an embedded FreeRegionNode.
    if (config_.block_size < sizeof(FreeRegionNode))
    {
        config_.block_size = sizeof(FreeRegionNode);
    }

    // Round up to the nearest multiple of block_alignment so that
    // contiguous block placement keeps every block aligned.
    //
    // The formula (value + alignment - 1) & ~(alignment - 1) works
    // because alignment is guaranteed to be a power of two (validated
    // by PoolConfig), making ~(alignment - 1) a bitmask that clears
    // the lower bits.
    std::size_t alignment = config_.block_alignment;
    config_.block_size = (config_.block_size + alignment - 1) & ~(alignment - 1);
}


void ProcessMemoryPool::compute_effective_chunk_geometry()
{
    // A chunk must hold at least one block.
    if (config_.chunk_size < config_.block_size)
    {
        config_.chunk_size = config_.block_size;
    }

    // Round up to the nearest multiple of block_size so that no space
    // is wasted at the tail of a chunk. The power-of-two bitmask trick
    // does not apply here because block_size is not necessarily a power
    // of two. Use arithmetic ceiling instead.
    std::size_t remainder = config_.chunk_size % config_.block_size;
    if (remainder != 0)
    {
        config_.chunk_size += config_.block_size - remainder;
    }

    blocks_per_chunk_ = config_.chunk_size / config_.block_size;
}


void ProcessMemoryPool::init_thread_cache_configuration()
{
    // Sanity: if initial batch is zero, default to 1 so that a thread's
    // first trip to the shared pool acquires at least one block.
    if (config_.initial_thread_batch == 0)
    {
        config_.initial_thread_batch = 1;
    }

    // Sanity: max batch must be >= initial batch.
    if (config_.max_thread_batch < config_.initial_thread_batch)
    {
        config_.max_thread_batch = config_.initial_thread_batch;
    }
}


void ProcessMemoryPool::init_allocator()
{
