/**
 * @file ProcessMemoryPool.cpp
 * @brief Implementation of the process-wide fixed-size block pool.
 *
 * Chevron Library — Internal Infrastructure
 */

#include "ProcessMemoryPool.hpp"

#include <stdexcept>
#include <new>  // std::bad_alloc

namespace chevron::memory {

// ============================================================================
// Construction / Destruction
// ============================================================================

ProcessMemoryPool::ProcessMemoryPool(const MemoryPoolConfig& config)
    : free_list_head_{ TaggedPointer{ nullptr, 0 } }
    , bytes_acquired_{ 0 }
    , config_{ config }
    , blocks_per_chunk_{ 0 }
    , allocator_{ 1 }  // Placeholder — properly reconstructed by init_allocator().
{
    config_.isValidOrThrow();

    compute_effective_block_geometry();
    compute_effective_chunk_geometry();
    init_thread_cache_configuration();
    init_allocator();
}


ProcessMemoryPool::~ProcessMemoryPool()
{
    // The allocator's destructor releases all acquired chunks back to
    // the OS. The pool's destructor has no additional cleanup beyond
    // what member destruction handles automatically.
}


// ============================================================================
// Construction Helpers (private)
// ============================================================================

void ProcessMemoryPool::compute_effective_block_geometry()
{
    // The block must be large enough to hold an embedded FreeRegionNode.
    std::size_t raw_block_size = config_.block_size.size_t_bytes();

    if (raw_block_size < sizeof(FreeRegionNode))
    {
        raw_block_size = sizeof(FreeRegionNode);
    }

    // Round up to the nearest multiple of block_alignment so that
    // contiguous block placement keeps every block aligned.
    //
    // The formula (value + alignment - 1) & ~(alignment - 1) works
    // because alignment is guaranteed to be a power of two (validated
    // by MemoryPoolConfig), making ~(alignment - 1) a bitmask that
    // clears the lower bits.
    std::size_t alignment = config_.block_alignment;
    raw_block_size = (raw_block_size + alignment - 1) & ~(alignment - 1);

    config_.block_size = Bytes{ raw_block_size };
}


void ProcessMemoryPool::compute_effective_chunk_geometry()
{
    std::size_t raw_chunk_size = config_.chunk_size.size_t_bytes();
    std::size_t raw_block_size = config_.block_size.size_t_bytes();

    // A chunk must hold at least one block.
    if (raw_chunk_size < raw_block_size)
    {
        raw_chunk_size = raw_block_size;
    }

    // Round up to the nearest multiple of block_size so that no space
    // is wasted at the tail of a chunk. The power-of-two bitmask trick
    // does not apply here because block_size is not necessarily a power
    // of two. Use arithmetic ceiling instead.
    std::size_t remainder = raw_chunk_size % raw_block_size;
    if (remainder != 0)
    {
        raw_chunk_size += raw_block_size - remainder;
    }

    config_.chunk_size = Bytes{ raw_chunk_size };
    blocks_per_chunk_ = raw_chunk_size / raw_block_size;
}


void ProcessMemoryPool::init_thread_cache_configuration()
{
    // Sanity: if initial blocks is zero, default to 1 so that a
    // thread's first trip to the shared pool acquires at least one block.
    if (config_.initial_thread_blocks == 0)
    {
        config_.initial_thread_blocks = 1;
    }

    // Sanity: max thread blocks must be >= initial thread blocks.
    if (config_.max_thread_blocks < config_.initial_thread_blocks)
    {
        config_.max_thread_blocks = config_.initial_thread_blocks;
    }

    // Sanity: max batch must be >= initial thread blocks and
    // <= max thread blocks.
    if (config_.max_thread_batch < config_.initial_thread_blocks)
    {
        config_.max_thread_batch = config_.initial_thread_blocks;
    }

    if (config_.max_thread_batch > config_.max_thread_blocks)
    {
        config_.max_thread_batch = config_.max_thread_blocks;
    }
}


void ProcessMemoryPool::init_allocator()
{
    // Derive the maximum number of OS-level acquisitions permitted.
    // This is the upper bound on how many chunks can fit within the
    // byte budget at the current chunk size. The allocator uses this
    // as its acquisition count ceiling — it does not enforce byte
    // budgets itself.
    std::size_t raw_ceiling = config_.budget_ceiling.size_t_bytes();
    std::size_t raw_chunk_size = config_.chunk_size.size_t_bytes();
    std::size_t max_acquisitions = raw_ceiling / raw_chunk_size;

    // Reconstruct the allocator in-place with the correct capacity.
    // Placement new over the placeholder-initialized member is necessary
    // because the max acquisition count depends on effective geometry
    // values that are not available until after the geometry helpers
    // have run.
    allocator_.~ProcessMemoryAllocator();

    new (&allocator_) ProcessMemoryAllocator(max_acquisitions);
}

} // namespace chevron::memory

