// ============================================================================
// Free List Operations (private)
// ============================================================================

void ProcessMemoryPool::push_batch(void* head, void* tail)
{
    // Load the current free list head. We'll link our chain's tail to
    // whatever the head currently points to, then CAS-swap the head
    // to point to our chain's first block.
    TaggedPointer expected = free_list_head_.load(std::memory_order_acquire);

    while (true)
    {
        // Link the tail of our chain to the current head of the shared
        // free list. This makes our chain an extension that, once the
        // CAS succeeds, seamlessly continues into the existing list.
        reinterpret_cast<FreeRegionNode*>(tail)->next = expected.ptr;

        // Prepare the new head — our chain's first block with an
        // incremented generation counter.
        TaggedPointer desired{ head, expected.generation + 1 };

        // Attempt the swap. If the head hasn't changed since our read,
        // this succeeds and our chain is now the front of the shared
        // free list. If another thread modified the head, the CAS fails,
        // 'expected' is updated to the current head, and we retry —
        // relinking the tail to the new head on the next iteration.
        if (free_list_head_.compare_exchange_weak(
                expected,
                desired,
                std::memory_order_release,
                std::memory_order_acquire
            ))
        {
            return;
        }

        // CAS failed — 'expected' now holds the current head.
        // Loop back: relink the tail and try again.
    }
}


void* ProcessMemoryPool::pop_batch(std::size_t batch_size)
{
    TaggedPointer expected = free_list_head_.load(std::memory_order_acquire);

    while (true)
    {
        // If the free list is empty, we cannot pop anything.
        if (expected.ptr == nullptr)
        {
            return nullptr;
        }

        // Walk the chain from the current head to find the last block
        // in the batch we want to detach, and the block after it which
        // will become the new head.
        //
        // We need to traverse batch_size blocks. After the walk:
        //   - 'batch_head' is the first block (what we return)
        //   - 'batch_tail' is the last block in the batch
        //   - 'new_head' is the block after the batch (or nullptr)
        void* batch_head = expected.ptr;
        void* batch_tail = batch_head;
        void* new_head = nullptr;

        std::size_t count = 1;

        while (count < batch_size)
        {
            void* next = reinterpret_cast<FreeRegionNode*>(batch_tail)->next;

            // If we run out of blocks before reaching batch_size, there
            // aren't enough blocks in the shared list to fill this batch.
            if (next == nullptr)
            {
                return nullptr;
            }

            batch_tail = next;
            ++count;
        }

        // The block after the batch tail becomes the new free list head.
        new_head = reinterpret_cast<FreeRegionNode*>(batch_tail)->next;

        // Attempt to swing the head from the expected position to the
        // block after our batch. If this succeeds, we've atomically
        // detached the entire batch from the shared free list.
        TaggedPointer desired{ new_head, expected.generation + 1 };

        if (free_list_head_.compare_exchange_weak(
                expected,
                desired,
                std::memory_order_release,
                std::memory_order_acquire
            ))
        {
            // Sever the detached batch from the rest of the list.
            // The batch is now a standalone chain from batch_head
            // to batch_tail with a null terminator.
            reinterpret_cast<FreeRegionNode*>(batch_tail)->next = nullptr;

            return batch_head;
        }

        // CAS failed — 'expected' now holds the current head.
        // The entire traversal is invalid because the list changed
        // underneath us. Loop back and start the walk from the new head.
    }
}

