{
    // Load the current free list head. We'll link our chain's tail to
    // whatever the head currently points to, then CAS-swap the head
    // to point to our chain's first block.
    TaggedPointer expected = free_list_head_.load(std::memory_order_acquire);

    while (true)
    {
        // Link the tail of our chain to the current head of the shared
        // free list. This makes our chain an extension that, once the
        // CAS succeeds, seamlessly continues into the existing list.
        reinterpret_cast<FreeRegionNode*>(tail)->next = expected.ptr;

