// ============================================================================
// Chunk Integration (private)
// ============================================================================

void ProcessMemoryPool::carve_and_thread(const MemoryRegion& region)
{
    // Walk the region from base to end in block_size steps, writing
    // an embedded FreeRegionNode at the start of each block. Each
    // node links to the next block. The last node's next is nullptr.
    //
    // This produces a standalone chain that is not yet part of the
    // shared free list. The memory being written to was just acquired
    // from the OS — no other thread has access to it.

    std::size_t raw_block_size = config_.block_size.size_t_bytes();
    auto* cursor = static_cast<std::byte*>(region.base);
    auto* end = cursor + region.size.size_t_bytes();

    auto* chain_head = reinterpret_cast<FreeRegionNode*>(cursor);
    FreeRegionNode* chain_tail = nullptr;

    while (cursor < end)
    {
        auto* current = reinterpret_cast<FreeRegionNode*>(cursor);
        std::byte* next_block = cursor + raw_block_size;

        if (next_block < end)
        {
            current->next = reinterpret_cast<FreeRegionNode*>(next_block);
        }
        else
        {
            // Last block in the chunk — terminate the chain.
            current->next = nullptr;
            chain_tail = current;
        }

        cursor = next_block;
    }

    // Prepend the entire chain onto the shared free list in one
    // atomic operation.
    push_batch(chain_head, chain_tail);
}


void ProcessMemoryPool::grow()
{
    // ---- Phase 1: Byte budget gate ------------------------------------------
    //
    // Atomically increment bytes_acquired_ by the chunk size. If the
    // result exceeds the budget ceiling, roll back and throw. This
    // check happens before the allocator call so we don't waste an
    // OS allocation on a chunk we can't afford.

    std::size_t raw_chunk_size = config_.chunk_size.size_t_bytes();
    std::size_t raw_ceiling = config_.budget_ceiling.size_t_bytes();

    std::size_t previous = bytes_acquired_.fetch_add(
        raw_chunk_size, std::memory_order_acq_rel
    );

    if (previous + raw_chunk_size > raw_ceiling)
    {
        bytes_acquired_.fetch_sub(raw_chunk_size, std::memory_order_relaxed);
        throw std::bad_alloc();
    }

    // ---- Phase 2: Chunk acquisition -----------------------------------------
    //
    // Delegate to the allocator for the OS allocation. If this fails,
    // roll back the byte budget and rethrow. The allocator independently
    // enforces its own acquisition count ceiling.

    MemoryRegion chunk{};

    try
    {
        chunk = allocator_.acquire_chunk(
            config_.chunk_size,
            config_.block_alignment
        );
    }
    catch (...)
    {
        bytes_acquired_.fetch_sub(raw_chunk_size, std::memory_order_relaxed);
        throw;
    }

    // ---- Phase 3: Carve and integrate ---------------------------------------
    //
    // Carve the acquired chunk into blocks, thread them into a chain,
    // and prepend the chain onto the shared free list.

    carve_and_thread(chunk);
}

} // namespace chevron::memory

