// ============================================================================
// Thread-Local Cache Access (private)
// ============================================================================

ProcessMemoryPool::ThreadLocalCache& ProcessMemoryPool::thread_cache()
{
    thread_local ThreadLocalCache cache{
        nullptr,                         // free_list_head — empty
        0,                               // cached_count
        config_.initial_thread_blocks,   // current_batch_size
        this                             // owner
    };

    return cache;
}


// ============================================================================
// ThreadLocalCache Methods
// ============================================================================

std::size_t ProcessMemoryPool::ThreadLocalCache::compute_growth_batch(
    std::size_t max_batch
)
{
    // Double the batch size for the next refill, capped at max_batch.
    // The current value is used for this refill, then updated.
    std::size_t batch = current_batch_size;

    std::size_t next = current_batch_size * 2;
    current_batch_size = (next <= max_batch) ? next : max_batch;

    return batch;
}


std::size_t ProcessMemoryPool::ThreadLocalCache::compute_drain_count(
    std::size_t max_blocks
) const
{
    // Drain down to half the maximum. This creates a buffer zone so
    // the cache doesn't drain on every single deallocation that
    // pushes past the limit.
    std::size_t target = max_blocks / 2;
    return cached_count - target;
}


void ProcessMemoryPool::ThreadLocalCache::drain()
{
    if (free_list_head == nullptr) return;

    // Walk the local chain to find the tail.
    FreeRegionNode* head = free_list_head;
    FreeRegionNode* tail = head;

    while (tail->next != nullptr)
    {
        tail = static_cast<FreeRegionNode*>(tail->next);
    }

    // Push the entire local chain back to the shared free list.
    owner->push_batch(head, tail);

    free_list_head = nullptr;
    cached_count = 0;
}


ProcessMemoryPool::ThreadLocalCache::~ThreadLocalCache()
{
    drain();
}


// ============================================================================
// Public Operations
// ============================================================================

MemoryRegion ProcessMemoryPool::allocate()
{
    ThreadLocalCache& cache = thread_cache();

    // Fast path — pop one block from the thread-local cache.
    if (cache.free_list_head != nullptr)
    {
        FreeRegionNode* block = cache.free_list_head;
        cache.free_list_head = static_cast<FreeRegionNode*>(block->next);
        cache.cached_count--;

        return MemoryRegion{ block, config_.block_size };
    }

    // Slow path — refill the cache from the shared free list.
    std::size_t batch = cache.compute_growth_batch(config_.max_thread_batch);
    FreeRegionNode* chain = pop_batch(batch);

    // If the shared list is empty, grow the pool and retry.
    if (chain == nullptr)
    {
        expand_memory();
        chain = pop_batch(batch);

        // If still nullptr after growth, the pool is exhausted.
        if (chain == nullptr)
        {
            throw std::bad_alloc();
        }
    }

    // Take the first block for the caller, cache the rest.
    FreeRegionNode* block = chain;
    cache.free_list_head = static_cast<FreeRegionNode*>(chain->next);

    // Count the remaining blocks in the chain for the cache count.
    std::size_t refilled = 0;
    FreeRegionNode* cursor = cache.free_list_head;
    while (cursor != nullptr)
    {
        refilled++;
        cursor = static_cast<FreeRegionNode*>(cursor->next);
    }
    cache.cached_count = refilled;

    return MemoryRegion{ block, config_.block_size };
}


void ProcessMemoryPool::deallocate(const MemoryRegion& region) noexcept
{
    ThreadLocalCache& cache = thread_cache();

    // Push the returned block onto the thread-local cache.
    auto* node = static_cast<FreeRegionNode*>(region.base());
    node->next = cache.free_list_head;
    cache.free_list_head = node;
    cache.cached_count++;

