void ProcessMemoryPool::deallocate(const MemoryRegion& region) noexcept
{
    ThreadLocalCache& cache = thread_cache();

    // Push the returned block onto the thread-local free list.
    auto* node = static_cast<FreeRegionNode*>(region.base());
    node->next = cache.free_list_head;
    cache.free_list_head = node;
    cache.free_count++;

    // If the free list exceeds the maximum, drain a batch back to
    // the shared free list to make blocks available to other threads.
    if (cache.free_count > config_.max_thread_blocks)
    {
        std::size_t drain_count = cache.compute_drain_count(
            config_.max_thread_blocks
        );

        // Detach drain_count blocks from the front of the local chain.
        FreeRegionNode* drain_head = cache.free_list_head;
        FreeRegionNode* drain_tail = drain_head;

        for (std::size_t i = 1; i < drain_count; i++)
        {
            drain_tail = static_cast<FreeRegionNode*>(drain_tail->next);
        }

        // The block after the drain tail becomes the new cache head.
        cache.free_list_head = static_cast<FreeRegionNode*>(drain_tail->next);
        drain_tail->next = nullptr;
        cache.free_count -= drain_count;
        cache.cached_count -= drain_count;

        push_batch(drain_head, drain_tail);
    }
}

