    // Process-level chunks can be hundreds of megabytes to gigabytes —
    // a redundant allocation could fatally exhaust system memory. The
    // first thread to arrive claims ownership of the expansion. All
    // other threads yield until the expansion completes, then return
    // without expanding — the free list will have blocks available.

    ExpansionState expected = ExpansionState::IDLE;

    if (!expansion_state_.compare_exchange_strong(
            expected,
            ExpansionState::EXPANDING,
            std::memory_order_acquire,
            std::memory_order_relaxed
        ))
    {
        // Another thread is already expanding. Yield until it finishes.
        while (expansion_state_.load(std::memory_order_acquire)
               == ExpansionState::EXPANDING)
        {
            std::this_thread::yield();
        }

        // The expanding thread has finished. The free list should now
        // have blocks available. Return and let the caller retry
        // pop_batch against the replenished shared free list.
        return;
    }

    // We own the expansion. Ensure the gate is reset on any exit path —
    // success, budget failure, or OS allocation failure.
    ScopeGuard expansionGuard{
        [&]() {
            expansion_state_.store(ExpansionState::IDLE, std::memory_order_release);
        }
    };

