    // ----->  PHASE 3 | (Chunk Acquisition)  <-----------------------------------------
    //
    // Delegate to the allocator for the OS allocation. If this fails,
    // both guards fire — the byte budget is rolled back and the expansion
    // gate is reset. The allocator independently enforces its own
    // acquisition count ceiling.

    MemoryRegion chunk = allocator_.acquire_chunk(
        config_.chunk_size,
        config_.block_alignment
    );

