    // ----->  PHASE 4 | (Chunk Integration)  <-----------------------------------------
    //
    // Carve the acquired chunk into blocks, thread them into a chain,
    // and prepend the chain onto the shared free list. Dismiss the byte
    // increment guard since the acquisition succeeded. The expansion
    // guard fires normally, resetting the gate to IDLE.

    byteIncrementGuard.dismiss();
    carve_and_thread(chunk);
}

