void ProcessMemoryPool::preallocate(std::size_t chunk_count)
{
    // Intended to be called during initialization before the pool
    // enters active concurrent use. Each iteration acquires a chunk,
    // carves it into blocks, and threads them into the shared free
    // list. The expansion gate inside expand_memory is not a concern
    // here — no other threads are running yet.
    for (std::size_t i = 0; i < chunk_count; ++i)
    {
        expand_memory();
    }
}


// ============================================================================
// Diagnostics
// ============================================================================

std::size_t ProcessMemoryPool::block_size() const noexcept
{
    return config_.block_size.size_t_bytes();
}


std::size_t ProcessMemoryPool::alignment() const noexcept
{
    return config_.block_alignment;
}


std::size_t ProcessMemoryPool::acquired_chunk_count() const noexcept
{
    return allocator_.acquired_count();
}


std::size_t ProcessMemoryPool::total_block_count() const noexcept
{
    return allocator_.acquired_count() * blocks_per_chunk_;
}


std::size_t ProcessMemoryPool::bytes_acquired() const noexcept
{
    return bytes_acquired_.load(std::memory_order_relaxed);
}


std::uint64_t ProcessMemoryPool::generation() const noexcept
{
    return free_list_head_.load(std::memory_order_relaxed).generation;
}

